import{_ as a,o as t,c as n,a3 as o}from"./chunks/framework.Dz5Q8p4s.js";const d=JSON.parse('{"title":"ROS2SmolVLA: Enabling Small Vision-Language-Action Models for Integration into Industrial-Grade Lightweight Robots","description":"","frontmatter":{"title":"ROS2SmolVLA: Enabling Small Vision-Language-Action Models for Integration into Industrial-Grade Lightweight Robots","arxiv":"2608.23320","date":"2026-08-24","authors":"Nils Mandischer, Noah Böckmann, Ludwig Holl, Lars Mikelsons","categories":"cs.RO","topics":"视觉语言动作模型, 工业部署, ROS 2","outline":[2,2]},"headers":[],"relativePath":"papers/2608.23320.md","filePath":"papers/2608.23320.md","lastUpdated":null}'),e={name:"papers/2608.23320.md"};function r(l,s,p,i,g,c){return t(),n("div",null,[...s[0]||(s[0]=[o('<h1 id="ros2smolvla-enabling-small-vision-language-action-models-for-integration-into-industrial-grade-lightweight-robots" tabindex="-1">ROS2SmolVLA: Enabling Small Vision-Language-Action Models for Integration into Industrial-Grade Lightweight Robots <a class="header-anchor" href="#ros2smolvla-enabling-small-vision-language-action-models-for-integration-into-industrial-grade-lightweight-robots" aria-label="Permalink to &quot;ROS2SmolVLA: Enabling Small Vision-Language-Action Models for Integration into Industrial-Grade Lightweight Robots&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2608.23320" target="_blank" rel="noreferrer">2608.23320</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-08-24（v1；已被 8th International Conference on Industry of the Future and Smart Manufacturing, Padua &amp; Venice, 2026 接收）</td></tr><tr><td><strong>作者</strong></td><td>Nils Mandischer, Noah Böckmann, Ludwig Holl, Lars Mikelsons（University of Augsburg, Chair of Mechatronics）</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>把 SmolVLA 通过一套开源 ROS 2 接口接到 Universal Robots UR10e 这类工业级轻型机器人上，用 349 条遥操作 episode 训一个 pick-and-place 策略，并用九组结构化测试把它的失败模式（尤其是「用蓝色作为放置触发」这一条）逐条挖出来。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/vla">视觉语言动作模型 VLA</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>制造业正从刚性顺序生产转向柔性自适应生产：批量更小、产品变体更多、从排产转向按需。传统机器人自动化在结构化环境里工作良好，但一条原本只跑单一工艺的产线，现在要应付很多工艺、还要对产品的微小变化作出反应，改造成本极高。</p><p>VLA 看上去是这个问题的解药——它从观测到的系统状态直接生成动作。但作者指出当前研究在两个方向上都绕开了工业现场：一类聚焦于<strong>大模型</strong>，算力必须外包到云上，随之而来的是合规与安全问题（工业客户往往不允许产线图像离开厂区）；另一类用的是 <strong>lab 级硬件</strong>（SO-101、OpenMANIPULATOR 这类小型教学臂），其控制回路、安全要求、负载与工作空间尺寸和真实产线差了一个量级，因此实验结论无法外推。</p><p>于是留下一个具体的空白：<strong>小 VLA 在工业级硬件上到底能不能用，能用到什么程度</strong>。这篇论文的价值不在算法创新，而在于它是少数把这个问题<strong>如实测量并公开负面结果</strong>的工作——包括它自己在结论里写下的那句「成功率目前对真实部署来说仍然太低」。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>大模型路线</strong>：RT-1 用标准 transformer 输出离散化控制指令，但开放词表泛化有限；RT-2 与 Open X-Embodiment 把 VLM 骨干（PaLI-X、PaLM-E）与机器人轨迹共训，把动作生成表述成 token 预测，因而继承了语义推理能力；OpenVLA 开源了 7B 的跨形态策略。这条路的问题在工业现场是双重的：推理延迟可能超过控制频率能接受的阈值；算力需求超出边缘设备，外包上云则触发合规与隐私红线。</p><p><strong>小模型路线</strong>：Octo（27M/93M）用块状掩码注意力 + 轻量扩散动作头，可在消费级硬件上微调；MiniVLA 用紧凑 Qwen 骨干 + 向量量化动作分块把 OpenVLA 缩到 1B；SmolVLA 只有 450M，明确面向消费级硬件与 CPU；PokeVLA 证明优化世界知识引导与视觉 token 可以补偿语言模型容量的下降。作者认可这条路的方向，但指出<strong>小模型语义泛化能力更弱、需要更专门化的部署</strong>，而这一点从未在工业约束下被系统评估过。</p><p><strong>参数高效微调路线</strong>：只微调动作头、或用 LoRA 往注意力与 MLP 层插低秩适配器，能大幅降低训练显存。这些是必要的工程手段，不解决「小模型在大工作空间里够不够用」这个问题。</p><p>作者对现状的总结很干脆：小 VLA 大多只在简单小型硬件上被基准过，<strong>这恰恰掩盖了它们在真实产线上的可用性</strong>。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>作为一个机电一体化实验室，出发点不是「怎么让 VLA 更强」，而是「怎么让 VLA 接到我们已有的 UR10e 上」。这条路径上的每个决定都由约束推出来：</p><ul><li>合规要求算力必须在厂内 → 排除云端大模型 → 选 450M 的 SmolVLA。</li><li>已有产线栈是 ROS 2，而 SmolVLA 生态在 LeRobot 里 → 必须写一层 broker（<code>lerobot-ros</code>）。</li><li>想跨形态复用 → 动作空间选<strong>笛卡尔</strong>而不是关节，这样换臂不必重训。</li><li>SmolVLA 每帧视觉 token 被硬限制在 64 个 → 图像信息密度成为一等约束 → 必须裁剪俯视图只留有效工作区。</li><li>遥操作采数据很贵 → 只采了 349 条 → 于是必须设计一个能从 349 条里读出<strong>结构化结论</strong>的测试计划，而不是只报一个平均成功率。</li></ul><p>最后这一步是本文方法论上最值得学的地方：九组测试（T1–T9）沿着立方体位置、立方体颜色、盒子位置、盒子颜色、盒子形状、机器人初始构型六个因子分别变化，且<strong>在测试前就定义好</strong>。这让每个失败都能被归因到一个具体因子上。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>工业现场对 VLA 的真正约束不是模型强不强，而是三件事：算力必须在厂内、硬件是工业级而非教学级、工作空间比实验室桌面大一个量级。把 450M 的 SmolVLA 接到 UR10e 上跑一遍，这三条约束会立刻把模型的真实瓶颈暴露出来——不是语义理解，而是<strong>每帧 64 个视觉 token 的信息预算</strong>，以及在这个预算下策略会退化成依赖颜色这类最省 token 的捷径。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以「把灰色立方体放进蓝色盒子」这一次执行走一遍。</p><p><strong>硬件层</strong>：UR10e + Robotiq Hand-E 平行夹爪；两台 Microsoft Azure Kinect 作为静态相机 + 一个末端 webcam；数据流在 Nvidia Jetson AGX Orin 边缘 PC 上处理与拼接；VLA 推理跑在一台消费级工作站（RTX 4080 16GB VRAM、32GB RAM）；三者用非管理型 10Gbit 交换机连接。这是一个<strong>边缘到工作站的解耦架构</strong>：实时硬件执行与重型多模态推理分离。</p><p><strong>控制抽象</strong>：通过标准 <code>ros2_control</code> 暴露四种交互方式——关节位置控制、关节轨迹插值、MoveIt Servo 的操作空间速度跟踪、以及向 Cartesian Motion Controller 发 <code>TwistStamped</code>。夹爪走轨迹控制器或 <code>(Parallel)GripperActionController</code>。状态经 <code>joint_state_broadcaster</code> 与 Cartesian 控制器的 <code>current_pose</code> 话题广播。用笛卡尔坐标而非直接关节控制，是为了方便移植到别的形态。</p><p><strong>数据采集</strong>：自研的 <code>lerobot-roscam</code> 把三路异步相机统一成 LeRobot 相机接口，支持色彩空间转换、旋转、自定义分辨率裁剪；<code>lerobot-ros</code> 负责连机器人、发指令、收本体感觉。数据集含三路相机、关节状态、末端笛卡尔位姿；<strong>动作用笛卡尔增量</strong>。</p><p><strong>训练数据</strong>：用手柄遥操作半结构化采集。为学到工作空间的空间关系，建了 <strong>5×5 的立方体位置网格</strong>，每个位置采 5 次、每次变化目标盒子位置；另加入多个不同颜色立方体的 episode；还专门加入<strong>错误恢复</strong> episode（抓歪或掉落后重新抓）。共 <strong>349 条</strong>，已开源在 Hugging Face。</p><p><strong>训练</strong>：从 SmolVLA 预训练权重微调，<code>train_expert_only=False</code>、<code>compile_model=True</code>。50,000 步的模型效果不行，加到 <strong>200,000 步</strong>后成功率显著改善，在一张 NVIDIA L40S 上训了约 25 小时。</p><p><strong>推理时</strong>：输入是末端笛卡尔位姿 + 三路视觉；俯视图<strong>裁掉上半部分</strong>只留有效工作区（为省视觉 token）；输出 <code>TwistStamped</code> 作用于末端。</p><p><strong>仿真孪生</strong>：<code>ur10e_vla_sim</code> 在 Gazebo 里复刻物理、相机配置与工位布局，ROS 2 控制 API 与话题 schema 与真机<strong>完全一致</strong>，因此容器化的策略可以互换部署。论文明确说明验证只用了真实数据，<strong>仿真器未被完整验证</strong>。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>九组测试，任务是把立方体放进盒子，prompt 统一为 <code>Pick up the [颜色] cube and put it in the [颜色] box.</code>（T6 省略立方体颜色）。评分拆成 pick（抓到且全程夹住）与 place（放进盒子），<strong>place 按总数计</strong>，因此抓失败也算 place 失败；若机器人自主恢复（掉了再捡起来）算成功。</p><p><strong>问题一：分布内的空间泛化如何？</strong> T1 变化盒子位置（ID）与立方体位置：BP 1 是 90%/90%、BP 7 是 100%/100%，但 <strong>BP 6 的 place 掉到 40%</strong>（pick 仍 100%）。作者归因为该工作区区域的训练数据覆盖不足。T2 换到 OOD 盒子位置后普遍退化，BP 5-3 掉到 40%/20%。</p><p><strong>问题二：初始构型影响多大？</strong> T3 变化机器人初始构型：多数在 70–90%，但 <strong>RC 5 掉到 50%</strong>。解释很具体——RC 5 远在相机起始视锥之外，腕相机在早期无法有效发现立方体位置。</p><p><strong>问题三：颜色泛化如何？</strong> T4/T5 变化立方体颜色：灰色 80%/80%，蓝色 60%/60%，黄色 50%/50%，OOD 的橙色 60%/60%。作者判定视觉模型对黄/橙存在偏置。</p><p><strong>问题四：能不能按 prompt 选颜色？</strong> 这是全文最重要的负面结果。T6 在场上放绿色与灰色两个立方体、prompt 不指定颜色：模型 <strong>75% 选绿色</strong>。T7 在 prompt 里指定颜色：要绿色时正确率 70%/70%（两种位置排列），<strong>要灰色时只有 20% 和 30%</strong>。作者的结论是「模型有效地忽略了这个条件，退回到它对绿色的固有偏好」，并明确写下：<strong>尽管 33% 的训练 episode 含多色立方体与明确的颜色 prompt，训练出的策略颜色辨别能力可以忽略不计</strong>。</p><p><strong>问题五：换容器还能放对吗？</strong> T8 用训练里没见过的黑色与橙色方盒：两者 pick 都是 100%，但黑盒 <strong>found box 只有 17%</strong>、place 17%；橙盒 found box 100% 却 place 仍只有 17%。T9 用蓝色圆盒与纸板盒：蓝色圆盒 100%/100%/100%，纸板盒 83%/50%/17%。</p><p>从 T8 的矛盾里作者做了一次<strong>真正的因果干预</strong>：橙盒能被稳定发现却几乎放不进去，说明策略是用<strong>腕相机里的蓝色</strong>来决定何时松爪的。他们通过在相机前手持一个蓝色物体<strong>手动验证</strong>了这一点。这是全篇最漂亮的一步——不是相关性观察，是可控实验。</p><p><strong>总体成绩</strong>（pick / place / 抓到后再放成功）：ID 情形（T1、T3、T4）78.33% / 72.50% / 92.47%；OOD 情形（T2、T5、T8、T9）76.56% / 46.88% / 61.22%；全体 77.72% / 63.59% / 81.69%。<strong>OOD 的抓取与 ID 基本持平，崩塌全部发生在放置环节</strong>，与蓝色触发假说一致。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：小 VLA 要在工业现场落地，缺的不是算法而是接到工业级硬件上的那一层，ROS2SmolVLA 用容器化 + <code>ros2_control</code> + LeRobot broker 把 SmolVLA 接到了 UR10e 并开源了全部代码、数据与模型；用 349 条遥操作 episode 训练（50k 步不够，200k 步才行，L40S 上约 25 小时），总体 pick 77.72% / place 63.59%；九组结构化测试把失败精确归因到具体因子——工作区某些区域数据覆盖不足、初始构型在相机视锥外、以及对颜色的强烈偏置；最重要的发现是策略把<strong>腕相机里的蓝色</strong>当成了放置动作的触发器，作者用手持蓝色物体做了直接验证，这解释了为什么 OOD 的 pick 几乎不掉而 place 从 72.50% 崩到 46.88%；作者自己的结论是成功率对真实部署仍然太低，并把原因归给训练数据不足。</p><p><strong>3 句话版</strong>：把 450M 的 VLA 接到工业臂上是可行的工程，但每帧 64 个视觉 token 的预算会逼策略去抓最省 token 的捷径——在这个数据集里就是颜色。33% 的训练 episode 带明确颜色指令，仍然没有换来可用的颜色辨别能力。做工业 VLA 评测时，按因子设计测试计划并对可疑捷径做手动干预验证，比多报几个平均成功率有用得多。</p><p><strong>1 句话版</strong>：小 VLA 在工业硬件上跑得起来，但它学到的是「看见蓝色就松爪」。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>观察到的失败是数据覆盖不足造成的，而不是模型容量或视觉 token 预算造成的</strong>。论文把几乎每一个负面结果都归因到「训练数据还不够」——BP 6 的 place 掉到 40% 归因于该区域覆盖不足，颜色偏置归因于样本群体不均衡，结论一节写的是「主要由于仍然缺少训练数据」。整篇论文对 SmolVLA 的正面判断（「适合需要在厂内计算的小型任务」）完全依赖这个归因成立。</p><p>它很可能不成立，而且论文自己给了反证。颜色那一项：<strong>33% 的训练 episode 已经包含多色立方体与明确的颜色 prompt</strong>，这个比例不算小，而颜色辨别能力仍然「可以忽略不计」。如果加数据是解药，33% 的比例本该至少带来部分能力。相反，「lessons learned」一节给出的机制解释指向<strong>容量与 token 预算</strong>：低输入分辨率导致模型定位不到腕相机视野外的物体（裁剪俯视图后才显著改善），激进的 token 优化导致被其他任务相关物体遮挡的立方体找不到。这两条都是架构约束，加数据不会消失。</p><p>论文缺的关键证据是一条<strong>数据规模曲线</strong>。349 条 episode 只是一个点。用 1/3、2/3、3/3 的数据各训一个 200k 步的模型，画出 place 成功率与颜色合规率随数据量的变化，就能把「数据不足」与「容量不足」区分开。没有这条曲线，「with suitable improvements, we assume that SmolVLA will be a viable model architecture」这句话只是一个假设，而作者也确实用了 assume 这个词。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周，全部在已开源的资产上做，不需要重新采数据。</p><ol><li>从 Hugging Face 拉 349 条 episode 的数据集与 200k 步的模型权重（论文都已公开）。</li><li>做<strong>数据消融</strong>：分别用随机抽取的 116 条（1/3）、233 条（2/3）与全部 349 条，各训一个 200,000 步模型，其余超参完全照论文（<code>train_expert_only=False</code>、<code>compile_model=True</code>）。</li><li>在<strong>同一组</strong> T4（颜色变化）与 T7（prompt 指定颜色）测试用例上评三个模型，每格重复 10 次。</li><li>记录两条曲线：place 成功率 vs 数据量，颜色合规率 vs 数据量。</li></ol><p><strong>判据</strong>：若颜色合规率随数据量单调且明显上升，作者的「数据不足」归因成立，工程路线就是继续采数据；若三条数据量下的颜色合规率都在 50% 上下抖动，那么瓶颈是每帧 64 个视觉 token 的信息预算或 450M 的容量，正确的下一步是改架构（提高有效分辨率、加深度通道）而不是加数据。这个实验的成本约为原论文训练开销的两倍，却能决定整条工程路线的方向。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>第一击：颜色合规率低于「永远抓绿色」这个常量策略。</strong></p><p>用论文自己的数字算一下（以下是我的计算，不是论文的声称）。T7 有四行：两颗立方体、prompt 绿 → 70% 正确；prompt 灰 → 20%；位置对调后 prompt 绿 → 70%；prompt 灰 → 30%。四行平均的颜色合规率是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">70</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">20</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">70</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">30</span><span class="mclose">)</span><span class="mord">/4</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">47.5%</span></span></span></span>。而一个<strong>完全不读 prompt、永远抓绿色</strong>的常量策略，在绿/灰各半的 prompt 分布下合规率恰好是 50%。也就是说，<strong>这个策略的颜色遵循能力略低于一个零参数的常量基线</strong>。T6 的 75% 选绿也与这个图像一致。论文明确说了颜色辨别「可以忽略不计」，但没有把这个平凡基线摆出来做对照——一旦摆出来，「模型学到了一点颜色能力只是不稳定」这种温和解读就被排除了。</p><p><strong>第二击：整个任务可能被一条经典 CV 流水线打败。</strong></p><p>作者已经证明策略是靠蓝色触发放置的。那么反方的构造很直接：写一条约 200 行的 OpenCV + 运动规划基线——俯视图做色块分割定位立方体、标定后反投影到机器人系、用已有的 Cartesian Motion Controller 走点、按位置阈值开合夹爪。这条基线不需要任何学习，在 T1/T3/T4 这类 ID 场景里很可能远超 78.33%/72.50%。如果确实如此，那么 VLA 在这个任务上的<strong>唯一</strong>可辩护价值就不是成功率，而是<strong>换型成本</strong>（换一个新工件需要多少人时）——而这恰恰是论文完全没有测量的量。缺了这个对照，「SmolVLA 适合小型任务」这个结论在工业读者眼里是没有说服力的：产线上没人会用 72.5% 的成功率替换一条 99% 的固定程序。</p><p><strong>第三击：实验环境是这项「工业验证」里最不工业的部分。</strong> 论文自己在 Figure 2 的说明里写明工位光照「通过遮光板、漫射顶灯与无频闪侧灯得到良好控制」。真实产线有天窗、有随班次变化的照度、有反光工件与油污。九组测试变化了立方体位置、颜色、盒子位置、颜色、形状与机器人构型，<strong>唯独没有变化光照</strong>，而 T4/T5/T8/T9 已经证明这个策略对颜色极度敏感。设计一组 T10：固定其他一切，只把色温与照度扫过三档，测 place 成功率。基于蓝色触发这一已被验证的机制，可以合理推断（这是推断，不是论文结论）成绩会显著下滑；若确实如此，那么「工业级验证」这个定位需要补上光照鲁棒性这一维才成立。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：论文报的是任务成功率，但工业买家买的不是成功率，是<strong>柔性</strong>——换一个批次、换一个工件、换一个夹具，从停线到复产要花多少人时。整篇论文的动机（小批量、多变体、按需生产）全在讲这个，可测量的指标却一个都没落到它上面。同时，「加数据就能好」这个假设在 §9 里已经被质疑，而验证它的实验（数据规模曲线）本身也只回答成功率，不回答柔性。</p><p><strong>新 framing</strong>：把评价对象从「策略的成功率」换成「<strong>产线的换型成本</strong>」，定义一个可复现的量：给定一个新工件变体，从零开始到策略在该变体上达到成功率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span>（比如 90%），所需的<strong>遥操作演示分钟数 + 微调墙钟小时数 + 工程师干预次数</strong>之和。记作 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span></span></span></span>。这个量的好处是它天然把 VLA 与经典方案放在同一把尺子上——重新示教一条 VLA 和重新编一段固定程序，都可以用同一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span></span></span></span> 度量。可借鉴的相邻领域工具来自主动学习与 few-shot 适配里的<strong>标注预算曲线</strong>，以及生产工程里已有的换型时间（changeover time）指标体系。</p><p><strong>第一个实验</strong>：在已有的 UR10e 工位上定义三个递进的变体——(V1) 换立方体颜色，(V2) 换成不同几何的工件（比如小圆柱），(V3) 换容器形状与材质（对应论文 T9 的纸板盒）。对每个变体，同时跑两条路径：路径 A 是继续采演示微调 ROS2SmolVLA，路径 B 是让一位熟练工程师改经典 CV + 运动规划流水线。两条路径都记录到达 90% 成功率所需的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span></span></span></span>，并画成柱状图。判据非常明确：如果 VLA 路径在 V1（只换颜色，语义上最简单）上的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span></span></span></span> 就已经不低于经典路径，那么小 VLA 在工业现场的价值主张目前不成立，研究重点应转向数据效率而非部署工程；如果 VLA 在 V2/V3 这类几何与材质变化上显著更便宜，那就找到了它真正的适用边界——<strong>不是省成功率，是省工程师</strong>。这个实验还有一个副产品：路径 A 的每个变体都会产生新的演示数据，正好可以拿来画 §10 那条缺失的数据规模曲线。</p>',60)])])}const h=a(e,[["render",r]]);export{d as __pageData,h as default};
